const STATS = [
  { valeur: '500+',  etiquette: 'Étudiants Formés',    icone: '🎓' },
  { valeur: '92%',   etiquette: 'Taux d\'Insertion',   icone: '💼' },
  { valeur: '15+',   etiquette: 'Formateurs Experts',   icone: '👨‍⚕️' },
  { valeur: 'Agréé', etiquette: 'Ministère MFPT',      icone: '🏛️' },
];

export default function BarreStatistiques() {
  return (
    <div className="py-12" style={{backgroundColor:'#0f1e34'}}>
      <div className="max-w-7xl mx-auto px-6 grid grid-cols-2 md:grid-cols-4 gap-6">
        {STATS.map((stat) => (
          <div key={stat.etiquette} className="text-center group py-2">
            <div className="text-3xl mb-2 group-hover:scale-110 transition-transform inline-block">
              {stat.icone}
            </div>
            <div className="font-titre text-2xl md:text-3xl font-bold mb-1" style={{color:'#d4a017'}}>
              {stat.valeur}
            </div>
            <div className="font-corps text-xs uppercase tracking-wider text-gray-400">
              {stat.etiquette}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
